describe('Table Column Freezing', () => {
    beforeEach(() => {
        cy.visit('/your-table-page-url'); // Replace with the actual URL of the page containing the table
    });

    it('should freeze the first column when scrolling horizontally', () => {
        cy.get('.table') // Replace with the actual selector for the table
            .scrollTo('right'); // Scroll horizontally to the right
        cy.get('.table .first-column') // Replace with the actual selector for the first column
            .should('have.css', 'position', 'sticky') // Check if the first column is sticky
            .and('have.css', 'left', '0px'); // Ensure it stays at the left
    });

    it('should not affect the visibility of other columns when scrolling', () => {
        cy.get('.table') // Replace with the actual selector for the table
            .scrollTo('right'); // Scroll horizontally to the right
        cy.get('.table .other-column') // Replace with the actual selector for another column
            .should('be.visible'); // Ensure other columns are still visible
    });
});
